/**
 * Compiles contracts/AnchorRegistry.sol and writes a typed viem-ready artifact.
 *
 * Run from anywhere:
 *   node scripts/compile-contract.mjs
 *
 * The generated file is src/lib/anchor/artifact.ts. It is safe to commit: it
 * contains only the ABI and deployment bytecode, never a key or an address.
 */
import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import solc from "solc";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const projectRoot = path.resolve(scriptDir, "..");
const sourcePath = path.join(projectRoot, "contracts", "AnchorRegistry.sol");
const relativeSource = "contracts/AnchorRegistry.sol";
const artifactPath = path.join(projectRoot, "src", "lib", "anchor", "artifact.ts");

const source = await fs.readFile(sourcePath, "utf8");

const input = {
  language: "Solidity",
  sources: {
    [relativeSource]: { content: source },
  },
  settings: {
    optimizer: { enabled: true, runs: 200 },
    // Base Sepolia supports Cancun; pin it so local and deployed bytecode match.
    evmVersion: "cancun",
    outputSelection: {
      "*": {
        "*": ["abi", "evm.bytecode.object"],
      },
    },
  },
};

let output;
try {
  output = JSON.parse(solc.compile(JSON.stringify(input)));
} catch (error) {
  console.error(`solc failed to run: ${error instanceof Error ? error.message : String(error)}`);
  process.exit(1);
}

const diagnostics = output.errors ?? [];
for (const diagnostic of diagnostics) {
  const severity = diagnostic.severity === "error" ? "ERROR" : "WARNING";
  console.error(`[${severity}] ${diagnostic.formattedMessage.trim()}`);
}

const errors = diagnostics.filter((diagnostic) => diagnostic.severity === "error");
if (errors.length > 0) {
  console.error(`\nCompilation failed with ${errors.length} error(s).`);
  process.exit(1);
}

const contract = output.contracts?.[relativeSource]?.AnchorRegistry;
if (!contract) {
  console.error(`Compilation produced no AnchorRegistry output for ${relativeSource}.`);
  process.exit(1);
}

const abi = contract.abi;
const bytecode = contract.evm?.bytecode?.object;
if (typeof bytecode !== "string" || bytecode.length === 0) {
  console.error("AnchorRegistry bytecode is empty.");
  process.exit(1);
}

const compilerVersion = solc.version();
const deploymentBytecode = `0x${bytecode}`;
const bytecodeBytes = bytecode.length / 2;
const warnings = diagnostics.filter((diagnostic) => diagnostic.severity !== "error");

const artifact = `/**
 * Generated by scripts/compile-contract.mjs. Do not edit by hand.
 * Source: ${relativeSource}
 * Compiler: ${compilerVersion}
 * Optimizer: enabled, runs 200. EVM: cancun.
 */

export const ANCHOR_ABI = ${JSON.stringify(abi, null, 2)} as const;

export const ANCHOR_BYTECODE = "${deploymentBytecode}" as const;
`;

await fs.mkdir(path.dirname(artifactPath), { recursive: true });
await fs.writeFile(artifactPath, artifact, "utf8");

console.log(`solc version: ${compilerVersion}`);
console.log(`contract:     AnchorRegistry (${relativeSource})`);
console.log(`optimizer:    enabled, runs 200`);
console.log(`bytecode:     ${bytecodeBytes} bytes (${bytecode.length} hex chars)`);
console.log(`artifact:     ${path.relative(projectRoot, artifactPath)}`);
console.log(`warnings:     ${warnings.length === 0 ? "none" : String(warnings.length)}`);
